// coding-misk · Cavo Scoperto
// song composed with sections and tracks: each track plays its clips, switched on by the section lane (1 plays, 0 is silent, values in between fade)
// each .analyze("…") lights up its instrument in the Stage visual
setcpm(126/4)

const SECTIONS = [['Crescendo', 16], ['Crescendo 2', 28], ['Corrente', 8], ['Tensione', 8], ['Scarica', 16], ['Blackout', 8], ['Scarica 2', 16], ['Fusibile', 4]]
const TEMPO = {'Crescendo': 126, 'Crescendo 2': 126, 'Corrente': 126, 'Tensione': 126, 'Scarica': 126, 'Blackout': 126, 'Scarica 2': 126, 'Fusibile': 126}

// section lanes: 1 plays, 0 is silent, values in between fade
const section1 = "<1!16 0!88>"  // Crescendo · 16 bars · 126 BPM · F# · F#m
const section2 = "<0!16 1!28 0!60>"  // Crescendo 2 · 28 bars · 126 BPM · F# · F#m F#m F#m G
const section3 = "<0!44 1!8 0!52>"  // Corrente · 8 bars · 126 BPM · F# · F#m F#m F#m G
const section4 = "<0!52 1!8 0!44>"  // Tensione · 8 bars · 126 BPM · F# · F#m F#m F#m G
const section5 = "<0!60 1!16 0.67 0.33 0!26>"  // Scarica · 16 bars · 126 BPM · F# · F#m F#m F#m G
const section6 = "<0!76 0.33 0.67 1!6 0!20>"  // Blackout · 8 bars · 126 BPM · F# · F#m · fades in over 2 bars
const section7 = "<0!84 1!16 0.5 0!3>"  // Scarica 2 · 16 bars · 126 BPM · G · Gm G# Gm F
const section8 = "<0!100 0.5 1!3>"  // Fusibile · 4 bars · 126 BPM · G · Gm · fades in over 1 bars

// ========== drums ==========
// Crescendo · bars 1-16 · pattern build~2
// Drums · RolandTR909
$: s("[bd ~ ~ ~] [bd ~ ~ ~] [bd ~ ~ ~] [bd ~ ~ ~]").bank("RolandTR909").gain(0.64).distort(1.2).distortvol(.5).mask(section1).velocity(section1).orbit(1).analyze("kick")
$: s("[hh ~ ~ ~] ~ ~ ~").bank("RolandTR909").gain(0.32).distort(1.2).distortvol(.5).mask(section1).velocity(section1).orbit(1).analyze("hats")
