$: s("[hh ~ ~ ~] ~ ~ ~").bank("RolandTR909").gain(0.32).distort(1.2).distortvol(.5).mask(section2).velocity(section2).orbit(1).analyze("hats")
// Corrente · bars 45-52 · pattern pulse~2
